export const GLOSSARY_SHARD = Object.freeze({"market-order":{"slug":"market-order","cat":"trading","en":"Market order","contentLocale":"vi","term":"Lệnh thị trường (Market order)","aka":["lệnh market","market order","lệnh thị trường"],"short":"Lệnh thị trường (market order) là lệnh mua hoặc bán ngay lập tức ở giá tốt nhất hiện có trong sổ lệnh, ưu tiên tốc độ khớp thay vì kiểm soát giá.","body":[["Khi đặt lệnh thị trường, bạn chỉ nhập số lượng hoặc số tiền, không nhập giá. Sàn lấy các lệnh đang chờ tốt nhất ở phía đối diện để khớp cho bạn. Vì lấy ",["thanh khoản","liquidity"]," từ ",["sổ lệnh","order-book"],", lệnh thị trường luôn chịu ",["phí taker","maker-taker-fees"],", thường cao hơn phí maker."],["Ưu điểm là gần như chắc chắn khớp, hữu ích khi bạn cần thoát vị thế gấp. Nhược điểm là bạn không biết trước giá khớp chính xác: với coin thanh khoản thấp, lệnh lớn hoặc lúc ",["biến động","volatility"]," mạnh, bạn có thể bị ",["trượt giá","slippage"]," đáng kể."],"Một số sàn có giới hạn bảo vệ giá cho lệnh thị trường, chỉ khớp trong một biên độ nhất định so với giá tham chiếu; phần vượt quá có thể bị hủy. Cách xử lý khác nhau giữa các sàn, hãy xem quy định trên trang hướng dẫn giao dịch."],"example":["Giả sử bạn bán 3 ",["BTC","bitcoin"]," bằng lệnh thị trường. Phía mua trong sổ lệnh có 1 BTC ở 59.990, 1,5 BTC ở 59.980 và 2 BTC ở 59.950. Lệnh của bạn khớp 1 BTC ở 59.990, 1,5 BTC ở 59.980 và 0,5 BTC ở 59.950, tổng 59.990 + 89.970 + 29.975 = 179.935 USDT. Với phí taker 0,05%, bạn trả thêm khoảng 90 USDT, nhận về khoảng 179.845 USDT."],"mistakes":["Dùng lệnh thị trường với coin có sổ lệnh mỏng và nhận giá khớp tệ hơn nhiều so với giá trên biểu đồ.","Đặt lệnh thị trường lớn ngay lúc có tin tức khi giá nhảy liên tục.","Quên rằng lệnh thị trường luôn chịu phí taker."],"faq":[{"q":"Khi nào nên dùng lệnh thị trường?","a":"Khi tốc độ quan trọng hơn giá, ví dụ cần thoát lệnh gấp hoặc giao dịch cặp có thanh khoản rất cao với số tiền nhỏ."},{"q":"Lệnh thị trường có bị trượt giá không?","a":"Có thể. Nếu khối lượng ở giá tốt nhất không đủ, lệnh sẽ khớp tiếp ở các mức giá kém hơn."}],"title":"Lệnh thị trường (market order) là gì?","description":"Lệnh thị trường là gì, khớp như thế nào trong sổ lệnh, vì sao chịu phí taker và khi nào dễ bị trượt giá.","related":[["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh."],["slippage","Trượt giá (Slippage)","Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý."],["maker-taker-fees","Phí maker và phí taker (Maker/Taker fee)","Phí maker và phí taker là hai mức phí giao dịch khác nhau: maker trả phí khi lệnh của bạn nằm chờ trên sổ lệnh và tạo thêm thanh khoản, taker trả phí khi lệnh của bạn khớp ngay với lệnh có sẵn."],["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng."],["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Thị trường, giới hạn, hủy lệnh: mỗi loại giải quyết điều gì?"},"coin":null,"tool":null,"cta":true},"arbitrage":{"slug":"arbitrage","cat":"trading","en":"Arbitrage","contentLocale":"vi","term":"Arbitrage (Kinh doanh chênh lệch giá)","aka":["arbitrage","arb","chênh lệch giá","kèo chênh lệch"],"short":"Arbitrage là chiến lược kiếm lời từ chênh lệch giá của cùng một tài sản giữa hai thị trường, bằng cách mua ở nơi rẻ và bán ở nơi đắt gần như cùng lúc.","body":[["Các dạng arbitrage phổ biến trong crypto gồm: chênh lệch giữa hai sàn, chênh lệch giữa spot và ",["hợp đồng tương lai","futures-contract"],", chênh lệch tam giác giữa ba ",["cặp giao dịch","trading-pair"]," trên cùng một sàn, và ",["arbitrage funding rate","funding-rate-arbitrage"],"."],["Trên lý thuyết là không rủi ro, nhưng thực tế có nhiều chi phí: phí giao dịch hai đầu, ",["phí rút tiền","withdrawal-fee"],", thời gian chuyển coin qua ",["blockchain","blockchain"],", ",["trượt giá","slippage"]," và rủi ro sàn tạm khóa nạp rút. Các chênh lệch lớn thường xuất hiện đúng lúc nạp rút bị gián đoạn."],"Thị trường cạnh tranh cao với bot chuyên nghiệp, nên chênh lệch dễ thấy thường biến mất trong vài giây. Bạn nên tính lợi nhuận ròng sau mọi chi phí trước khi hành động."],"example":"Giả sử một coin có giá 1,000 USDT ở sàn A và 1,015 USDT ở sàn B. Bạn mua 10.000 coin ở sàn A với giá 10.000 USDT, phí taker 0,1% là 10 USDT. Phí rút là 50 coin, nên chỉ 9.950 coin đến sàn B. Bán ở 1,015 thu 10.099 USDT, trừ phí 0,1% còn khoảng 10.089 USDT. Lãi ròng chỉ khoảng 79 USDT, và sẽ mất nếu giá ở sàn B giảm 1% trong lúc chờ chuyển.","mistakes":["Chỉ nhìn chênh lệch giá mà quên phí rút và thời gian xác nhận trên blockchain.","Không kiểm tra sàn đích có đang mở nạp coin trên đúng mạng lưới hay không.","Dùng lệnh thị trường lớn ở cặp thanh khoản mỏng, khiến trượt giá ăn hết chênh lệch."],"faq":[{"q":"Arbitrage crypto có còn lãi không?","a":"Vẫn có, nhưng chênh lệch giữa các sàn lớn thường rất nhỏ và bị bot khai thác nhanh. Lợi nhuận phụ thuộc vào chi phí, tốc độ và vốn của bạn."},{"q":"Arbitrage có rủi ro không?","a":"Có: rủi ro giá thay đổi khi đang chuyển coin, sàn khóa nạp rút, trượt giá và lỗi thao tác. Arbitrage không phải lợi nhuận chắc chắn."}],"title":"Arbitrage là gì? Kinh doanh chênh lệch giá crypto","description":"Arbitrage là gì, các dạng chênh lệch giá trong crypto và cách tính lợi nhuận ròng sau phí, trượt giá và thời gian chuyển.","related":[["funding-rate-arbitrage","Arbitrage funding rate (Kinh doanh chênh lệch funding)","Arbitrage funding rate là chiến lược giữ vị thế trung lập về giá, thường là mua spot và short perpetual cùng lượng, để thu khoản funding được trả định kỳ."],["bid-ask-spread","Chênh lệch giá mua-bán (Spread)","Chênh lệch giá mua-bán (bid-ask spread) là khoảng cách giữa giá mua cao nhất (bid) và giá bán thấp nhất (ask) trong sổ lệnh, và là chi phí ngầm mỗi khi bạn mua rồi bán ngay bằng lệnh thị trường."],["market-maker","Nhà tạo lập thị trường (Market maker)","Nhà tạo lập thị trường (market maker) là cá nhân hoặc tổ chức liên tục đặt lệnh mua và lệnh bán cho một tài sản để cung cấp thanh khoản và kiếm lời từ chênh lệch giá."],["withdrawal-fee","Phí rút tiền (withdrawal fee)","Phí rút tiền là khoản phí sàn thu khi bạn chuyển crypto từ tài khoản sàn ra ví hoặc sàn khác, thường là một số coin cố định tùy theo mạng blockchain bạn chọn."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"perpetual-futures":{"slug":"perpetual-futures","cat":"derivatives","en":"Perpetual futures (perps)","contentLocale":"vi","term":"Hợp đồng tương lai vĩnh cửu (Perpetual)","aka":["perpetual","perp","hợp đồng vĩnh cửu","futures vĩnh cửu"],"short":"Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot.","body":["Với hợp đồng thông thường, giá hội tụ về giá spot vào ngày đáo hạn. Perpetual không có ngày đó, nên sàn dùng funding: định kỳ, phe long trả cho phe short khi giá hợp đồng cao hơn chỉ số, và ngược lại. Khoản phí này kéo giá perp về gần giá spot.",["Perpetual là sản phẩm phái sinh có khối lượng lớn nhất trong crypto. Bạn có thể giữ vị thế bao lâu tùy ý, miễn là còn đủ ký quỹ. Sàn dùng ",["giá đánh dấu (mark price)","mark-price"]," để tính ",["lãi lỗ chưa thực hiện","unrealized-pnl"]," và ",["thanh lý","liquidation"],", tránh việc một cú giật giá ngắn làm cháy tài khoản hàng loạt."],["Chu kỳ funding phổ biến là 8 giờ, nhưng một số sàn và cặp dùng 1, 2 hoặc 4 giờ. Ngoài ",["sàn tập trung","centralized-exchange"],", còn có ",["DEX","dex"]," perp on-chain như Hyperliquid. Hãy kiểm tra trang thông số hợp đồng của sàn bạn dùng."]],"example":["Giả sử bạn short 2 ",["ETH","ethereum"]," perpetual ở giá 3.200 USDT, giá trị vị thế 6.400 USDT, và giữ trong 3 ngày. Funding thanh toán mỗi 8 giờ, mỗi lần +0,01%, nghĩa là long trả cho short. Mỗi lần bạn nhận 6.400 × 0,01% = 0,64 USDT, sau 9 lần nhận khoảng 5,76 USDT. Nếu giá ETH lên 3.300 USDT, bạn vẫn lỗ 200 USDT trên vị thế, nhiều hơn rất nhiều so với funding nhận được."],"mistakes":["Giữ vị thế perp nhiều tuần mà không tính tổng funding phải trả.","Nghĩ rằng giá perp luôn bằng đúng giá spot.","Bỏ qua giờ thanh toán funding khi mở vị thế sát thời điểm đó."],"faq":[{"q":"Perpetual là gì?","a":"Là hợp đồng tương lai không có ngày đáo hạn. Giá được giữ gần giá spot nhờ funding rate trả định kỳ giữa long và short."},{"q":"Hợp đồng vĩnh cửu có giữ được mãi không?","a":"Có, miễn là bạn còn đủ ký quỹ và không bị thanh lý. Tuy vậy bạn phải trả hoặc nhận funding trong suốt thời gian giữ."}],"title":"Hợp đồng vĩnh cửu (perpetual) là gì? Cách hoạt động","description":"Hợp đồng tương lai vĩnh cửu là gì, funding rate giữ giá perp bám spot ra sao và những chi phí khi giữ vị thế lâu.","related":[["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."],["mark-price","Giá đánh dấu (Mark price)","Giá đánh dấu (mark price) là giá tham chiếu mà sàn dùng để tính lãi lỗ chưa thực hiện và quyết định thanh lý, được xây dựng từ giá chỉ số của nhiều sàn spot."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."],["futures-contract","Hợp đồng tương lai (Futures)","Hợp đồng tương lai là thỏa thuận mua hoặc bán một tài sản theo giá xác định, cho phép bạn kiếm lời từ biến động giá mà không cần sở hữu tài sản thật."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Giao ngay và tương lai: bạn không mua cùng một thứ"},"coin":null,"tool":"/funding-rates","cta":true},"delivery-futures":{"slug":"delivery-futures","cat":"derivatives","en":"Delivery (quarterly) futures","contentLocale":"vi","term":"Hợp đồng tương lai giao sau (Delivery futures)","aka":["hợp đồng quý","futures quý","delivery futures","hợp đồng có kỳ hạn"],"short":"Hợp đồng tương lai giao sau là hợp đồng có ngày đáo hạn cố định, ví dụ theo tuần hoặc theo quý, và được tất toán theo giá chỉ số vào thời điểm đáo hạn.","body":[["Khác với perpetual, hợp đồng giao sau không có ",["funding rate","funding-rate"],". Thay vào đó, giá hợp đồng có thể cao hơn hoặc thấp hơn giá spot, gọi là basis, và khoảng chênh này thu hẹp dần khi gần đến ngày đáo hạn."],"Trên hầu hết sàn crypto, hợp đồng giao sau được tất toán bằng tiền chứ không giao coin thật. Vào thời điểm đáo hạn, vị thế còn mở sẽ tự đóng theo giá tất toán, thường là giá trung bình của chỉ số trong một khoảng thời gian ngắn trước giờ đáo hạn.",["Loại hợp đồng này phù hợp cho ",["phòng hộ","hedging"]," có kỳ hạn rõ ràng hoặc giao dịch basis. Tên gọi sản phẩm, chu kỳ ",["niêm yết","token-listing"]," và cách tính giá tất toán khác nhau giữa các sàn."]],"example":["Giả sử ",["BTC","bitcoin"]," spot ở 60.000 ",["USDT","usdt"]," và hợp đồng quý đáo hạn sau 90 ngày đang giao dịch ở 61.500 USDT, basis là 1.500 USDT hay 2,5%. Một người giữ BTC spot có thể bán 1 hợp đồng quý tương đương 1 BTC. Đến ngày đáo hạn, giá hợp đồng hội tụ về giá spot, nên dù BTC lên hay xuống, phần chênh 1.500 USDT ban đầu gần như được giữ lại, tương đương khoảng 10% một năm trước phí."],"mistakes":["Quên ngày đáo hạn và bất ngờ khi vị thế bị tất toán tự động.","Nghĩ rằng hợp đồng quý có funding giống perpetual.","So sánh giá hợp đồng quý với spot mà không tính thời gian còn lại đến đáo hạn."],"faq":[{"q":"Hợp đồng quý khác hợp đồng vĩnh cửu thế nào?","a":"Hợp đồng quý có ngày đáo hạn và không có funding. Hợp đồng vĩnh cửu không đáo hạn nhưng trả hoặc nhận funding định kỳ."},{"q":"Đến ngày đáo hạn thì sao?","a":"Vị thế còn mở được đóng theo giá tất toán của sàn, lãi lỗ chuyển vào tài khoản. Phần lớn sàn crypto không giao coin thật."}],"title":"Hợp đồng tương lai giao sau (hợp đồng quý) là gì?","description":"Hợp đồng tương lai giao sau là gì, basis và ngày đáo hạn hoạt động thế nào, khác hợp đồng vĩnh cửu ở điểm nào.","related":[["futures-contract","Hợp đồng tương lai (Futures)","Hợp đồng tương lai là thỏa thuận mua hoặc bán một tài sản theo giá xác định, cho phép bạn kiếm lời từ biến động giá mà không cần sở hữu tài sản thật."],["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["futures-basis","Basis hợp đồng tương lai (Futures basis)","Basis là chênh lệch giữa giá hợp đồng tương lai và giá spot (hoặc giá chỉ số) của cùng một tài sản, thường được thể hiện bằng số tiền hoặc tỷ lệ phần trăm năm."],["hedging","Phòng hộ (Hedging)","Phòng hộ (hedging) là việc mở một vị thế ngược chiều để giảm rủi ro biến động giá của tài sản bạn đang nắm giữ, đổi lại bằng việc hạn chế phần lợi nhuận."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Giao ngay và tương lai: bạn không mua cùng một thứ"},"coin":null,"tool":"/topics/derivatives","cta":false},"initial-margin":{"slug":"initial-margin","cat":"derivatives","en":"Initial margin","contentLocale":"vi","term":"Ký quỹ ban đầu (Initial margin)","aka":["initial margin","IM","ký quỹ mở vị thế"],"short":"Ký quỹ ban đầu là số tiền tối thiểu bạn phải đặt cọc để mở một vị thế có đòn bẩy, bằng giá trị vị thế chia cho đòn bẩy.","body":[["Công thức cơ bản: ký quỹ ban đầu = giá trị vị thế / ",["đòn bẩy","leverage"],". Vị thế 5.000 ",["USDT","usdt"]," với đòn bẩy 10x cần 500 USDT ký quỹ ban đầu. Một số sàn cộng thêm phần phí đóng vị thế dự kiến vào số tiền bị khóa khi mở lệnh."],["Ký quỹ ban đầu khác với ",["ký quỹ duy trì","maintenance-margin"],". Ký quỹ ban đầu là điều kiện để mở vị thế; ký quỹ duy trì là mức tối thiểu để vị thế không ",["bị thanh lý","liquidation"],". Khoảng cách giữa hai mức này quyết định giá có thể đi ngược bao xa."],"Nhiều sàn áp dụng hệ thống bậc rủi ro: vị thế càng lớn, đòn bẩy tối đa càng thấp, nên tỷ lệ ký quỹ ban đầu càng cao. Bạn nên xem bảng bậc rủi ro của cặp mình giao dịch."],"example":"Giả sử bạn muốn mở short 20 LINK ở 15 USDT, giá trị vị thế 300 USDT. Với đòn bẩy 3x, ký quỹ ban đầu là 300 / 3 = 100 USDT. Nếu tăng đòn bẩy lên 15x, ký quỹ ban đầu chỉ còn 20 USDT, nhưng vị thế vẫn trị giá 300 USDT và giá LINK chỉ cần tăng khoảng 6% là đã ăn gần hết số ký quỹ đó.","mistakes":["Nghĩ rằng ký quỹ ban đầu là số tiền tối đa bạn có thể mất, trong khi ở ký quỹ chéo bạn có thể mất nhiều hơn.","Không biết rằng vị thế lớn bị giới hạn đòn bẩy theo bậc rủi ro.","Nhầm ký quỹ ban đầu với ký quỹ duy trì."],"faq":[{"q":"Cách tính ký quỹ ban đầu?","a":"Lấy giá trị vị thế chia cho đòn bẩy. Vị thế 2.000 USDT với 4x cần 500 USDT ký quỹ ban đầu."},{"q":"Ký quỹ ban đầu khác ký quỹ duy trì thế nào?","a":"Ký quỹ ban đầu dùng để mở vị thế; ký quỹ duy trì là mức tối thiểu phải giữ để không bị thanh lý. Ký quỹ duy trì luôn thấp hơn."}],"title":"Ký quỹ ban đầu (initial margin) là gì? Cách tính","description":"Ký quỹ ban đầu là gì, công thức tính theo đòn bẩy và vì sao nó khác ký quỹ duy trì trong giao dịch hợp đồng tương lai.","related":[["maintenance-margin","Ký quỹ duy trì (Maintenance margin)","Ký quỹ duy trì là mức ký quỹ tối thiểu bạn phải giữ để vị thế có đòn bẩy không bị thanh lý."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."],["isolated-margin","Ký quỹ cô lập (Isolated margin)","Ký quỹ cô lập là chế độ trong đó mỗi vị thế có một khoản ký quỹ riêng, nên nếu bị thanh lý bạn chỉ mất phần ký quỹ đã gán cho vị thế đó."],["margin-trading","Giao dịch ký quỹ (Margin trading)","Giao dịch ký quỹ là việc vay thêm vốn từ sàn, dùng tài sản của bạn làm tài sản đảm bảo, để mở vị thế lớn hơn số tiền bạn có."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Tại sao bạn có thể bị đóng vị thế trước khi tiền ký quỹ về không?"},"coin":null,"tool":null,"cta":false},"portfolio-margin":{"slug":"portfolio-margin","cat":"derivatives","en":"Portfolio margin","contentLocale":"vi","term":"Ký quỹ danh mục (Portfolio margin)","aka":["portfolio margin","PM","ký quỹ theo danh mục"],"short":"Ký quỹ danh mục là chế độ tính ký quỹ dựa trên rủi ro tổng thể của cả danh mục, cho phép các vị thế phòng hộ lẫn nhau được giảm yêu cầu ký quỹ.","body":[["Thay vì tính ký quỹ riêng cho từng vị thế, sàn mô phỏng nhiều kịch bản giá và ",["biến động","volatility"],", rồi đặt yêu cầu ký quỹ theo mức lỗ lớn nhất của cả danh mục. Nếu bạn long spot ",["BTC","bitcoin"]," và short hợp đồng BTC cùng lượng, rủi ro ròng gần bằng 0 nên yêu cầu ký quỹ thấp hơn nhiều."],["Chế độ này phổ biến với người giao dịch chuyên nghiệp dùng kết hợp spot, futures và ",["quyền chọn","options"],". Nhiều sàn chỉ mở ký quỹ danh mục cho tài khoản có số dư hoặc cấp độ nhất định."],["Lợi ích về vốn đi kèm rủi ro: hiệu quả vốn cao khiến dễ dùng ",["đòn bẩy","leverage"]," lớn hơn, và nếu mối tương quan giữa các vị thế bị phá vỡ, yêu cầu ký quỹ có thể tăng đột ngột."]],"example":["Giả sử bạn giữ 2 BTC spot và short 2 BTC perpetual, khi BTC ở 50.000 ",["USDT","usdt"],". Nếu tính riêng, ",["vị thế short","long-and-short"]," 100.000 USDT với đòn bẩy 10x cần 10.000 USDT ký quỹ. Với ký quỹ danh mục, sàn thấy lãi lỗ hai vị thế gần như bù trừ, nên chỉ yêu cầu ký quỹ cho rủi ro còn lại, ví dụ vài nghìn USDT. Phần vốn được giải phóng có thể dùng việc khác, nhưng cũng dễ bị dùng để tăng đòn bẩy."],"mistakes":["Bật ký quỹ danh mục mà không hiểu sàn mô phỏng kịch bản rủi ro thế nào.","Dùng phần ký quỹ được giải phóng để mở thêm vị thế không phòng hộ.","Cho rằng hai tài sản tương quan cao sẽ luôn bù trừ nhau."],"faq":[{"q":"Portfolio margin khác cross margin thế nào?","a":"Cross margin dùng chung số dư nhưng vẫn tính ký quỹ từng vị thế. Portfolio margin tính theo rủi ro ròng của cả danh mục nên vị thế phòng hộ cần ít ký quỹ hơn."},{"q":"Ai nên dùng ký quỹ danh mục?","a":"Chủ yếu là người giao dịch có kinh nghiệm, dùng nhiều vị thế phòng hộ và theo dõi rủi ro thường xuyên."}],"title":"Ký quỹ danh mục (portfolio margin) là gì?","description":"Ký quỹ danh mục là gì, cách sàn tính rủi ro ròng của cả danh mục và lợi ích, rủi ro khi giảm yêu cầu ký quỹ.","related":[["cross-margin","Ký quỹ chéo (Cross margin)","Ký quỹ chéo là chế độ trong đó toàn bộ số dư khả dụng của tài khoản được dùng chung làm ký quỹ cho các vị thế, giúp hạn chế thanh lý sớm nhưng có thể khiến bạn mất cả tài khoản."],["isolated-margin","Ký quỹ cô lập (Isolated margin)","Ký quỹ cô lập là chế độ trong đó mỗi vị thế có một khoản ký quỹ riêng, nên nếu bị thanh lý bạn chỉ mất phần ký quỹ đã gán cho vị thế đó."],["unified-trading-account","Tài khoản giao dịch hợp nhất (UTA)","Tài khoản giao dịch hợp nhất là loại tài khoản gộp spot, ký quỹ, hợp đồng tương lai và quyền chọn vào một ví duy nhất, cho phép dùng chung tài sản làm ký quỹ."],["hedging","Phòng hộ (Hedging)","Phòng hộ (hedging) là việc mở một vị thế ngược chiều để giảm rủi ro biến động giá của tài sản bạn đang nắm giữ, đổi lại bằng việc hạn chế phần lợi nhuận."]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"Ký quỹ chéo: vì sao một vị thế lỗ có thể ảnh hưởng đến các vị thế khác"},"coin":null,"tool":null,"cta":false},"short-squeeze":{"slug":"short-squeeze","cat":"derivatives","en":"Short squeeze","contentLocale":"vi","term":"Short squeeze (Ép short)","aka":["short squeeze","ép short","squeeze"],"short":"Short squeeze là hiện tượng giá tăng nhanh buộc nhiều người đang short phải đóng vị thế hoặc bị thanh lý, và lệnh mua bắt buộc của họ lại đẩy giá tăng tiếp.","body":[["Đóng một ",["vị thế short","long-and-short"]," nghĩa là mua vào. Khi giá tăng, các ",["lệnh cắt lỗ","stop-loss"]," của phe short và lệnh ",["thanh lý","liquidation"]," đều là lệnh mua. Nếu nhiều vị thế short dồn vào gần một vùng giá, việc kích hoạt chúng tạo ra chuỗi lệnh mua liên tiếp, đẩy giá lên nhanh hơn bình thường."],["Dấu hiệu thị trường dễ bị ép short gồm: ",["funding rate","funding-rate"]," âm sâu, open interest cao, nhiều tài khoản short và ",["thanh khoản","liquidity"]," mỏng. Khi squeeze xảy ra, OI thường giảm nhanh vì vị thế short bị đóng."],["Hiện tượng ngược lại là long squeeze, khi giá giảm làm phe long bị thanh lý dây chuyền. Cả hai thường diễn ra nhanh và đi kèm ",["trượt giá","slippage"]," lớn."]],"example":"Giả sử một altcoin ở 2,00 USDT và có khoảng 5 triệu USDT vị thế short với giá thanh lý trong vùng 2,10-2,20. Một lệnh mua lớn đẩy giá lên 2,10, kích hoạt thanh lý đầu tiên. Lệnh mua bắt buộc tiếp theo đẩy giá lên 2,20 rồi 2,35 chỉ trong vài phút, tăng 17,5%. Sau khi phe short bị quét, lực mua cưỡng bức biến mất và giá có thể quay đầu.","mistakes":["Short coin thanh khoản thấp khi funding đã âm sâu và nhiều người cùng short.","Đuổi mua giữa cú squeeze, khi lực mua chủ yếu là bắt buộc và có thể dừng đột ngột.","Đặt cắt lỗ short ngay trên đỉnh cũ, nơi nhiều người khác cũng đặt."],"faq":[{"q":"Short squeeze là gì?","a":"Là khi giá tăng khiến phe short phải mua lại hoặc bị thanh lý, tạo thêm lực mua đẩy giá tăng tiếp."},{"q":"Làm sao nhận biết nguy cơ short squeeze?","a":"Theo dõi funding âm, open interest cao, tỷ lệ short lớn và dữ liệu thanh lý. Không chỉ báo nào đảm bảo squeeze sẽ xảy ra."}],"title":"Short squeeze là gì? Hiện tượng ép short trong crypto","description":"Short squeeze là gì, vì sao thanh lý phe short đẩy giá tăng dây chuyền và các dấu hiệu thị trường dễ bị ép short.","related":[["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."],["short-selling","Bán khống (Short selling)","Bán khống là việc bán một tài sản bạn không sở hữu, bằng cách vay hoặc dùng hợp đồng phái sinh, với kỳ vọng mua lại ở giá thấp hơn để kiếm lời."],["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."],["open-interest","Hợp đồng mở (Open interest)","Hợp đồng mở (open interest, OI) là tổng số lượng hoặc giá trị các hợp đồng phái sinh đang còn mở và chưa được đóng hay tất toán tại một thời điểm."]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"usdc":{"slug":"usdc","cat":"stablecoins","en":"USDC","contentLocale":"vi","term":"USDC (USD Coin)","aka":["USD Coin","USDC","Circle USDC"],"short":"USDC là stablecoin do công ty Circle phát hành, neo 1:1 với đô la Mỹ và được đảm bảo bằng tiền mặt cùng tài sản ngắn hạn tương đương tiền.","body":[["Circle công bố thông tin dự trữ của USDC định kỳ, phần lớn là tiền mặt tại ngân hàng và tín phiếu kho bạc Mỹ ngắn hạn. USDC có mặt trên nhiều ",["blockchain","blockchain"]," như ",["Ethereum","ethereum"],", Solana, Base, Arbitrum, và Circle có giao thức chuyển USDC gốc giữa các chuỗi bằng cách đốt và phát hành lại."],["USDC được dùng nhiều trong ",["DeFi","defi"],", thanh toán và các ",["perp DEX","perp-dex"]," như Hyperliquid, nơi USDC là tài sản ký quỹ chính. Tại EU, Circle chọn hướng tuân thủ khung ",["MiCA","mica"],", nên USDC thường vẫn có sẵn cho người dùng EU khi một số ",["stablecoin","stablecoin"]," khác bị hạn chế."],"USDC cũng từng mất neo: tháng 3/2023, khi ngân hàng Silicon Valley Bank sụp đổ và một phần dự trữ bị kẹt ở đó, USDC tạm thời giảm xuống dưới 0,9 USD rồi hồi lại sau vài ngày. Giống USDT, Circle có thể đóng băng USDC tại địa chỉ bị chỉ định."],"example":"Giả sử bạn giữ 20.000 USDC trong ví khi xảy ra một sự kiện tương tự năm 2023 và giá tạm xuống 0,88 USD. Giá trị trên màn hình chỉ còn 17.600 USD. Nếu hoảng loạn bán ngay, bạn chốt lỗ 2.400 USD. Nếu dự trữ sau đó được xác nhận an toàn và giá về 1 USD, người giữ không bán lấy lại đủ giá trị, nhưng không có gì bảo đảm điều đó trong mọi trường hợp.","mistakes":["Nghĩ rằng USDC không bao giờ lệch khỏi 1 USD.","Nhầm USDC gốc với USDC.e hoặc phiên bản qua cầu nối trên một số chuỗi.","Gửi USDC trên Solana vào địa chỉ nạp chỉ hỗ trợ Ethereum."],"faq":[{"q":"USDC khác USDT thế nào?","a":"Cả hai neo theo USD nhưng do hai công ty khác nhau phát hành: USDC của Circle, USDT của Tether. Chúng khác nhau về cơ cấu dự trữ, mức độ công bố và vị thế pháp lý ở từng khu vực."},{"q":"USDC.e là gì?","a":"Là USDC được đưa sang một chuỗi qua cầu nối, khác với USDC gốc do Circle phát hành trực tiếp trên chuỗi đó. Một số sàn và ứng dụng chỉ chấp nhận một trong hai loại."}],"title":"USDC là gì? Stablecoin của Circle giải thích","description":"USDC là gì, Circle đảm bảo USDC ra sao, khác USDT thế nào, sự kiện mất neo 2023 và lưu ý khi chọn mạng chuyển USDC.","related":[["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["usdt","USDT (Tether)","USDT là stablecoin do công ty Tether phát hành, neo theo tỷ lệ 1 USDT bằng 1 USD và là đồng ổn định được giao dịch nhiều nhất trên các sàn crypto."],["depeg","Depeg (mất neo giá)","Depeg là tình trạng một stablecoin hoặc token được neo giá rời khỏi mức giá mục tiêu của nó, ví dụ USDT hay USDC giao dịch ở 0,97 USD thay vì 1 USD."],["mica","MiCA (Luật thị trường tài sản mã hóa của EU)","MiCA là bộ quy định chung của Liên minh châu Âu về tài sản mã hóa, đặt ra yêu cầu cấp phép cho nhà cung cấp dịch vụ và quy tắc riêng cho stablecoin."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT có phải là đô la không? Tại sao mua coin lại thấy nó khắp nơi?"},"coin":{"slug":"usdc","name":"USDC","symbol":"USDC"},"tool":null,"cta":false},"launchpool":{"slug":"launchpool","cat":"exchange-features","en":"Launchpool","contentLocale":"vi","term":"Launchpool","aka":["launch pool","đào coin mới","farming token mới"],"short":"Launchpool là chương trình trên sàn cho phép bạn khóa token như BNB hay stablecoin trong một thời gian để nhận miễn phí token mới của dự án sắp niêm yết.","body":["Binance Launchpool là ví dụ nổi tiếng nhất, nhiều sàn khác như Bybit, Bitget hay OKX có chương trình tương tự với tên gọi riêng. Mỗi đợt có vài pool, mỗi pool nhận một loại token, và tổng phần thưởng được chia mỗi giờ hoặc mỗi ngày theo tỷ lệ số tiền bạn khóa so với toàn pool.",["Bạn không mất số token đã khóa và thường có thể rút ra bất kỳ lúc nào, phần thưởng chỉ tính trong thời gian còn khóa. Rủi ro chính nằm ở giá của token bạn khóa và giá của token mới khi bắt đầu giao dịch, vốn thường ",["biến động","volatility"]," mạnh."],["Nhiều pool có trần cá nhân và yêu cầu ",["KYC","kyc"],". Khi pool đông người tham gia, phần thưởng trên mỗi đơn vị giảm. Hãy đọc thông báo chính thức về thời gian, trần và cách tính phần thưởng."]],"example":["Giả sử một pool phát 1.000.000 token XYZ mỗi ngày và tổng số tiền khóa trong pool tương đương 100 triệu ",["USDT","usdt"],". Bạn khóa 2.000 USDT, tức 0,002% pool. Mỗi ngày bạn nhận khoảng 20 XYZ. Nếu chương trình kéo dài 5 ngày và lượng khóa không đổi, bạn nhận 100 XYZ. Giá trị thực tế phụ thuộc vào giá XYZ khi ",["niêm yết","token-listing"],", có thể cao hoặc thấp hơn kỳ vọng."],"mistakes":["Mua token để tham gia pool ở giá đỉnh, rồi khoản lỗ trên token đó lớn hơn phần thưởng.","Tính lợi nhuận dựa trên lượng khóa đầu đợt, trong khi pool đông dần và phần thưởng giảm.","Nhầm Launchpool với Launchpad, hai sản phẩm có cơ chế khác nhau."],"faq":[{"q":"Tham gia Launchpool có mất tiền gốc không?","a":"Số token khóa không bị trừ, nhưng giá trị của chúng vẫn biến động theo thị trường. Phần thưởng là token mới, giá trị tùy vào giá niêm yết."},{"q":"Launchpool khác Launchpad thế nào?","a":"Launchpool cho token mới miễn phí theo số tiền bạn khóa. Launchpad là đợt mở bán, bạn bỏ tiền ra mua token với giá đợt bán."}],"title":"Launchpool là gì? Cách nhận token mới miễn phí","description":"Launchpool cho phép khóa token để nhận token mới trước niêm yết. Tìm hiểu cách tính phần thưởng, trần, rủi ro và ví dụ cụ thể.","related":[["launchpad","Launchpad (mở bán token)","Launchpad là nền tảng mở bán token mới, nơi người dùng đăng ký mua token của dự án trước khi niêm yết, thường với giá cố định và số lượng phân bổ có hạn."],["staking","Staking","Staking là việc khóa coin của một blockchain proof-of-stake để giúp xác thực giao dịch và bảo vệ mạng lưới, đổi lại nhận phần thưởng bằng chính coin đó."],["airdrop","Airdrop","Airdrop là việc một dự án phát token miễn phí vào ví của người dùng đủ điều kiện, thường để thưởng người dùng sớm, phân phối token rộng hơn hoặc quảng bá dự án."],["token-listing","Niêm yết token (listing)","Niêm yết token là việc một sàn giao dịch chính thức thêm một token vào danh sách để người dùng có thể nạp, rút và giao dịch với các cặp nhất định."]],"lesson":null,"coin":null,"tool":"/activities","cta":true}});
